detector_raw:
{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this packing plan — for example, minimize the number of containers used, maximize the total tons of goods shipped, or something else?"
  ],
  "rationale": "The response asks a single clarification question about the objective of the packing plan, offering examples but requesting one specific policy choice."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are all available goods required to be shipped, or is it acceptable to leave some units of any type unshipped?"
  ],
  "rationale": "The response contains a single clarification question asking for a policy choice regarding whether all goods must be shipped or if unshipped units are permitted."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is the number of containers available unlimited, or is there a fixed fleet size that must be used?"
  ],
  "rationale": "The response asks a single clarification question regarding the availability of containers, presenting a binary choice between unlimited and fixed fleet size."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are the goods units indivisible (each unit must be whole, so container loads are integer numbers of units), or can units be split fractionally?"
  ],
  "rationale": "The response asks a single clarification question regarding the divisibility of goods units."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "The 18-ton minimum and 60-ton maximum weight limits — do they apply to every container that is used, or only to containers that actually contain goods?"
  ],
  "rationale": "The response asks a single clarification question about the scope of the weight limits."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "The rule \"if a container contains any type A then it must also contain at least one type C\" — does this apply to every used container, including containers that contain no A at all?"
  ],
  "rationale": "The response contains a single clarification question asking for the scope of applicability of a specific rule."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "The minimum of 12 units of type D per container — does this apply to every used container, or only to containers that contain at least one unit of type D?"
  ],
  "rationale": "The response asks for a single policy clarification regarding the scope of the minimum unit constraint, presenting two mutually exclusive options for one decision."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Can a container contain zero units of a particular goods type (e.g., a container with no type B), as long as the other rules are satisfied?"
  ],
  "rationale": "The response contains a single clarification question asking about the validity of empty slots for specific goods types within a container."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there any limit on how many units of a single goods type can go into one container, or is the only per-container restriction the 18–60 ton weight range, the 12-unit D minimum, and the A-implies-C rule?"
  ],
  "rationale": "The response asks a single clarification question about whether there are additional per-container restrictions beyond the listed ones."
}
